<?php require 'config.php';if(empty($_SESSION['user_id']))go('login.php');$r=null;$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM complaints WHERE complaint_code=? AND user_id=?');$s->execute([strtoupper(trim($_POST['code']??'')),$_SESSION['user_id']]);$r=$s->fetch();if(!$r)$err='Complaint not found in your account.';}$title='Track Complaint';require 'partials/top.php';?><section class="glass panel formpanel"><h3>Track a Complaint</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Complaint ID</label><input name="code" required placeholder="NML261028-ABC123"><button>Track Complaint</button></form><?=$err?'<div class="alert">'.e($err).'</div>':''?><?php if($r):?><h3><?=e($r['complaint_code'])?> — <?=e($r['title'])?></h3><p>Status: <b><?=e($r['status'])?></b></p><p>Admin remarks: <?=e($r['admin_remarks']??'No remarks yet')?></p><?php endif;?></section><?php require 'partials/bottom.php';?>